diff --git a/libs/editor/tokencertificates.cpp b/libs/editor/tokencertificates.cpp
new file mode 100644
index 000000000..69abdd2f8
--- /dev/null
+++ b/libs/editor/tokencertificates.cpp
@@ -0,0 +1,133 @@
+/*
+    SPDX-FileCopyrightText: 2026 Niccolò Venerandi <niccolo@venerandi.com>
+
+    SPDX-License-Identifier: LGPL-2.1-only OR LGPL-3.0-only OR LicenseRef-KDE-Accepted-LGPL
+*/
+
+#include "tokencertificates.h"
+
+#include <KLocalizedString>
+
+#include <QtConcurrentRun>
+
+#ifdef HAVE_P11KIT
+#include <p11-kit/p11-kit.h>
+#include <p11-kit/uri.h>
+#endif
+
+#ifdef HAVE_P11KIT
+static QByteArray objectAttribute(CK_FUNCTION_LIST *module, CK_SESSION_HANDLE session, CK_OBJECT_HANDLE object, CK_ATTRIBUTE_TYPE type)
+{
+    CK_ATTRIBUTE attribute = {type, nullptr, 0};
+    if (module->C_GetAttributeValue(session, object, &attribute, 1) != CKR_OK || attribute.ulValueLen == CK_UNAVAILABLE_INFORMATION) {
+        return {};
+    }
+    QByteArray value(attribute.ulValueLen, '\0');
+    attribute.pValue = value.data();
+    if (module->C_GetAttributeValue(session, object, &attribute, 1) != CKR_OK) {
+        return {};
+    }
+    return value;
+}
+
+static QList<TokenCertificates::Certificate> tokenCertificates()
+{
+    QList<TokenCertificates::Certificate> certificates;
+
+    CK_FUNCTION_LIST **modules = p11_kit_modules_load_and_initialize(0);
+    if (!modules) {
+        return certificates;
+    }
+
+    for (CK_FUNCTION_LIST **it = modules; *it; ++it) {
+        CK_FUNCTION_LIST *module = *it;
+        // Trust modules only hold the system's certificate authorities
+        if (p11_kit_module_get_flags(module) & P11_KIT_MODULE_TRUSTED) {
+            continue;
+        }
+
+        CK_ULONG slotCount = 0;
+        if (module->C_GetSlotList(CK_TRUE, nullptr, &slotCount) != CKR_OK || !slotCount) {
+            continue;
+        }
+        QList<CK_SLOT_ID> slotIds(slotCount);
+        if (module->C_GetSlotList(CK_TRUE, slotIds.data(), &slotCount) != CKR_OK) {
+            continue;
+        }
+
+        for (CK_ULONG i = 0; i < slotCount; ++i) {
+            CK_TOKEN_INFO tokenInfo;
+            CK_SESSION_HANDLE session;
+            if (module->C_GetTokenInfo(slotIds[i], &tokenInfo) != CKR_OK
+                || module->C_OpenSession(slotIds[i], CKF_SERIAL_SESSION, nullptr, nullptr, &session) != CKR_OK) {
+                continue;
+            }
+            const QString tokenLabel = QString::fromUtf8(reinterpret_cast<const char *>(tokenInfo.label), sizeof(tokenInfo.label)).trimmed();
+
+            CK_OBJECT_CLASS certificateClass = CKO_CERTIFICATE;
+            CK_ATTRIBUTE classAttribute = {CKA_CLASS, &certificateClass, sizeof(certificateClass)};
+            if (module->C_FindObjectsInit(session, &classAttribute, 1) == CKR_OK) {
+                CK_OBJECT_HANDLE object;
+                CK_ULONG count;
+                while (module->C_FindObjects(session, &object, 1, &count) == CKR_OK && count == 1) {
+                    QByteArray label = objectAttribute(module, session, object, CKA_LABEL);
+                    QByteArray id = objectAttribute(module, session, object, CKA_ID);
+
+                    P11KitUri *uri = p11_kit_uri_new();
+                    *p11_kit_uri_get_token_info(uri) = tokenInfo;
+                    p11_kit_uri_set_attribute(uri, &classAttribute);
+                    if (!label.isEmpty()) {
+                        CK_ATTRIBUTE labelAttribute = {CKA_LABEL, label.data(), static_cast<CK_ULONG>(label.size())};
+                        p11_kit_uri_set_attribute(uri, &labelAttribute);
+                    }
+                    if (!id.isEmpty()) {
+                        CK_ATTRIBUTE idAttribute = {CKA_ID, id.data(), static_cast<CK_ULONG>(id.size())};
+                        p11_kit_uri_set_attribute(uri, &idAttribute);
+                    }
+
+                    char *uriString = nullptr;
+                    if (p11_kit_uri_format(uri, P11_KIT_URI_FOR_OBJECT_ON_TOKEN, &uriString) == P11_KIT_URI_OK) {
+                        certificates.append({QString::fromUtf8(label), tokenLabel, QString::fromUtf8(uriString)});
+                        free(uriString);
+                    }
+                    p11_kit_uri_free(uri);
+                }
+                module->C_FindObjectsFinal(session);
+            }
+            module->C_CloseSession(session);
+        }
+    }
+
+    p11_kit_modules_finalize_and_release(modules);
+    return certificates;
+}
+#endif
+
+bool TokenCertificates::isSupported()
+{
+#ifdef HAVE_P11KIT
+    return true;
+#else
+    return false;
+#endif
+}
+
+bool TokenCertificates::isUri(const QString &location)
+{
+    return location.startsWith(QLatin1String("pkcs11:"));
+}
+
+QFuture<QList<TokenCertificates::Certificate>> TokenCertificates::find()
+{
+#ifdef HAVE_P11KIT
+    return QtConcurrent::run(tokenCertificates);
+#else
+    return QtFuture::makeReadyValueFuture(QList<Certificate>());
+#endif
+}
+
+QString TokenCertificates::displayName(const Certificate &certificate)
+{
+    const QString name = certificate.label.isEmpty() ? i18n("Unnamed certificate") : certificate.label;
+    return i18nc("@item certificate name (smart card or token name)", "%1 (%2)", name, certificate.tokenLabel);
+}
