+#ifndef PLASMA_NM_TOKEN_CERTIFICATES_H
+#define PLASMA_NM_TOKEN_CERTIFICATES_H
+
+#include "plasmanm_editor_export.h"
+
+#include <QFuture>
+#include <QList>
+#include <QString>
+
+class PLASMANM_EDITOR_EXPORT TokenCertificates
+{
+public:
+    struct Certificate {
+        QString label;
+        QString tokenLabel;
+        QString uri;
+    };
+
+    // Whether certificates on smart cards and security tokens can be listed
+    static bool isSupported();
+
+    // Whether a certificate or key location is a PKCS#11 URI rather than a file
+    static bool isUri(const QString &location);
+
+    // Lists the certificates on smart cards and security tokens in a worker thread,
+    // since loading the PKCS#11 modules can take a long time
+    static QFuture<QList<Certificate>> find();
+
+    static QString displayName(const Certificate &certificate);
+};
+
+#endif // PLASMA_NM_TOKEN_CERTIFICATES_H
