--- /dev/null
+++ b/libs/editorqml/qml/vpn/openconnect/OpenconnectTokenCertificate.qml
@@ -0,0 +1,98 @@
+/*
+    SPDX-FileCopyrightText: 2026 Niccolò Venerandi <niccolo@venerandi.com>
+
+    SPDX-License-Identifier: LGPL-2.1-only OR LGPL-3.0-only OR LicenseRef-KDE-Accepted-LGPL
+*/
+
+import QtQuick
+import QtQuick.Controls as QQC2
+import QtQuick.Layouts
+import org.kde.kirigami as Kirigami
+
+Kirigami.Dialog {
+    id: dialog
+
+    required property var setting
+
+    property var certificates: []
+
+    parent: QQC2.Overlay.overlay
+
+    title: i18nc("@title:window", "Select Certificate")
+
+    standardButtons: Kirigami.Dialog.Ok | Kirigami.Dialog.Cancel
+
+    preferredWidth: Kirigami.Units.gridUnit * 28
+
+    Component.onCompleted: {
+        const okButton = dialog.standardButton(Kirigami.Dialog.Ok);
+        if (okButton) {
+            okButton.enabled = Qt.binding(() => certificateList.currentIndex >= 0);
+        }
+    }
+
+    onOpened: {
+        dialog.certificates = [];
+        dialog.setting.findTokenCertificates();
+    }
+
+    onAccepted: {
+        if (certificateList.currentIndex < 0) {
+            return;
+        }
+
+        // OpenConnect finds the private key next to the certificate on the token
+        dialog.setting.userCert = dialog.certificates[certificateList.currentIndex].uri;
+        dialog.setting.userKey = "";
+    }
+
+    Connections {
+        target: dialog.setting
+
+        function onTokenCertificatesFound(certificates) {
+            dialog.certificates = certificates;
+            certificateList.currentIndex = certificates.length > 0 ? 0 : -1;
+        }
+    }
+
+    ListView {
+        id: certificateList
+
+        implicitHeight: Kirigami.Units.gridUnit * 10
+
+        clip: true
+        currentIndex: -1
+        model: dialog.certificates
+
+        delegate: QQC2.ItemDelegate {
+            required property int index
+            required property var modelData
+
+            width: ListView.view.width
+
+            text: modelData.name
+            highlighted: ListView.isCurrentItem
+
+            onClicked: certificateList.currentIndex = index
+            onDoubleClicked: {
+                certificateList.currentIndex = index;
+                dialog.accept();
+            }
+        }
+
+        QQC2.BusyIndicator {
+            anchors.centerIn: parent
+
+            visible: dialog.setting.findingTokenCertificates
+            running: visible
+        }
+
+        Kirigami.PlaceholderMessage {
+            anchors.centerIn: parent
+            width: parent.width - Kirigami.Units.gridUnit * 4
+
+            visible: !dialog.setting.findingTokenCertificates && certificateList.count === 0
+            text: i18n("No certificates were found on smart cards or security tokens.")
+        }
+    }
+}
