@@ -492,6 +501,39 @@ void OpenconnectSetting::setPreventInvalidCert(bool prevent)
     Q_EMIT validChanged();
 }

+bool OpenconnectSetting::tokenCertificatesSupported() const
+{
+    return TokenCertificates::isSupported();
+}
+
+bool OpenconnectSetting::findingTokenCertificates() const
+{
+    return m_findingTokenCertificates;
+}
+
+void OpenconnectSetting::findTokenCertificates()
+{
+    if (m_findingTokenCertificates) {
+        return;
+    }
+    m_findingTokenCertificates = true;
+    Q_EMIT findingTokenCertificatesChanged();
+
+    TokenCertificates::find().then(this, [this](const QList<TokenCertificates::Certificate> &certificates) {
+        QVariantList result;
+        for (const TokenCertificates::Certificate &certificate : certificates) {
+            result.append(QVariantMap{
+                {QStringLiteral("name"), TokenCertificates::displayName(certificate)},
+                {QStringLiteral("uri"), certificate.uri},
+            });
+        }
+
+        m_findingTokenCertificates = false;
+        Q_EMIT findingTokenCertificatesChanged();
+        Q_EMIT tokenCertificatesFound(result);
+    });
+}
+
