+void OpenconnectSettingWidget::selectTokenCertificate()
+{
+    Q_D(OpenconnectSettingWidget);
+
+    d->ui.buUserCertToken->setEnabled(false);
+    setCursor(Qt::BusyCursor);
+
+    TokenCertificates::find().then(this, [this](const QList<TokenCertificates::Certificate> &certificates) {
+        Q_D(OpenconnectSettingWidget);
+
+        d->ui.buUserCertToken->setEnabled(true);
+        unsetCursor();
+
+        if (certificates.isEmpty()) {
+            KMessageBox::information(this, i18n("No certificates were found on smart cards or security tokens."));
+            return;
+        }
+
+        QStringList names;
+        for (const TokenCertificates::Certificate &certificate : certificates) {
+            names.append(TokenCertificates::displayName(certificate));
+        }
+
+        bool ok = false;
+        const QString name = QInputDialog::getItem(this, i18nc("@title:window", "Select Certificate"), i18n("Certificate:"), names, 0, false, &ok);
+        if (!ok) {
+            return;
+        }
+
+        // OpenConnect finds the private key next to the certificate on the token
+        d->ui.leUserCert->setText(certificates.at(names.indexOf(name)).uri);
+        d->ui.leUserPrivateKey->clear();
+    });
+}
